def solve(n):
    def backtrack(path, diffs):
        if len(path) == n:
            return list(path)

        for i in range(n):
            if i not in path:
                if len(path) == 0:
                    path.append(i)
                    res = backtrack(path, diffs)
                    if res: return res
                    path.pop()
                else:
                    d = abs(i - path[-1])
                    if d not in diffs:
                        path.append(i)
                        diffs.add(d)
                        res = backtrack(path, diffs)
                        if res: return res
                        diffs.remove(d)
                        path.pop()
        return None
    return backtrack([], set())

